if ( ! function_exists( 'wpmcp_test_create_amelia_tables' ) ) {
	function wpmcp_test_create_amelia_tables(): void {
		global $wpdb;
		foreach ( wpmcp_test_amelia_tables() as $table => $columns ) {
			$wpdb->query( "DROP TABLE IF EXISTS {$wpdb->prefix}amelia_{$table}" ); // phpcs:ignore WordPress.DB.PreparedSQL.InterpolatedNotPrepared -- test fixture DDL built from literals.
			$wpdb->query( "CREATE TABLE {$wpdb->prefix}amelia_{$table} ({$columns}) DEFAULT CHARSET=utf8mb4" ); // phpcs:ignore WordPress.DB.PreparedSQL.InterpolatedNotPrepared -- test fixture DDL built from literals.
		}
	}
}

if ( ! function_exists( 'wpmcp_test_drop_amelia_tables' ) ) {
	function wpmcp_test_drop_amelia_tables(): void {
		global $wpdb;
		foreach ( array_keys( wpmcp_test_amelia_tables() ) as $table ) {
			$wpdb->query( "DROP TABLE IF EXISTS {$wpdb->prefix}amelia_{$table}" ); // phpcs:ignore WordPress.DB.PreparedSQL.InterpolatedNotPrepared -- test fixture DDL built from literals.
		}
	}
